input.newString:
// Opt out of static prerendering to ensure the timestamp is dynamic
export const dynamic = 'force-dynamic';

export default function Home() {
  // Get current server timestamp
  const serverTimestamp = new Date().toISOString();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server time: <strong>{serverTimestamp}</strong></p>
      <p>This timestamp is generated on the server for each request and will be different on every page load.</p>
    </main>
  );
}

